              "syntaxAnalysis": "复合句。People are invited to query Marilyn Vos Savant 为主句；who 引导非限制性定语从句修饰 Savant；分号后 that 引导并列句，that 指代前面的测试表现；破折号后 the highest score ever recorded 为同位语解释 228。",
