                "chinese": "令人百思不得其解的是，这件事情竟然会让任何一位企业老板感到意外吃惊。",
                "syntaxAnalysis": "主系表复合句。The mystery 作主语；is 为系动词；that 引导表语从句，从句中 should 表示竟然/居然的情感色彩，come as a surprise to sb 为固定搭配。",
