              "syntaxAnalysis": "谚语倒装/省略否定结构。It 为形式主语；rains 为谓语；but 相当于 except that 或 without，表示‘每次下雨都必定是倾盆大雨’，常考生动引语借以引出后文连锁危机的爆发。",
              "sIndex": 1,
